function rounded(x,y,w,h,r,fill,stroke){ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=1;ctx.stroke()}}
function drawWorld(){
 ctx.fillStyle='#c9dfc2';ctx.fillRect(0,0,W,H);
 // Waterfront and grassy public spaces
 ctx.fillStyle='#9bd0c5';ctx.fillRect(0,1595,W,305);
 for(let i=0;i<13;i++){ctx.beginPath();ctx.moveTo(i*235-30,1600);ctx.bezierCurveTo(i*235+20,1640,i*235-10,1670,i*235+30,1710);ctx.lineTo(i*235+60,1710);ctx.lineTo(i*235+20,1600);ctx.fillStyle='rgba(243,255,225,.2)';ctx.fill()}
 ctx.fillStyle='#e7d4a9';ctx.fillRect(0,1580,W,24);ctx.fillStyle='#c79d70';ctx.fillRect(0,1604,W,8);
 // Parcels, small sidewalk strips and flower gardens
 for(let y=0;y<1800;y+=400)for(let x=0;x<W;x+=500){ctx.fillStyle=((x/500+y/400)%2)?'#cde0c3':'#d0e2c7';ctx.fillRect(x+8,y+12,480,370);ctx.fillStyle='#e8dfc7';ctx.fillRect(x+15,y+15,470,10)}
 for(const p of parks){ctx.fillStyle='#acd29e';ctx.fillRect(p.x,p.y,p.w,p.h);for(let i=0;i<Math.floor(p.w/20);i++){ctx.fillStyle=i%2?'#e98e83':'#e7c56e';ctx.beginPath();ctx.arc(p.x+8+i*20,p.y+p.h/2,2.4,0,Math.PI*2);ctx.fill()}}
 // Streets with curb, paving and dashed sun-yellow center lines
 for(const r of roads){ctx.fillStyle='#e7ddc6';ctx.fillRect(r.x-5,r.y-5,r.w+10,r.h+10);ctx.fillStyle='#979c8c';ctx.fillRect(r.x,r.y,r.w,r.h);ctx.fillStyle='#a5a998';ctx.fillRect(r.x,r.y+4,r.w,r.h-8);
  if(r.w>r.h){ctx.strokeStyle='#e7d291';ctx.lineWidth=2;ctx.setLineDash([17,19]);ctx.beginPath();ctx.moveTo(r.x,r.y+r.h/2);ctx.lineTo(r.x+r.w,r.y+r.h/2);ctx.stroke();ctx.setLineDash([]);for(let x=r.x+32;x<r.x+r.w;x+=108){ctx.fillStyle='rgba(244,239,216,.58)';ctx.fillRect(x,r.y+9,26,4);ctx.fillRect(x,r.y+r.h-13,26,4)}}
  else{ctx.strokeStyle='#e7d291';ctx.lineWidth=2;ctx.setLineDash([17,19]);ctx.beginPath();ctx.moveTo(r.x+r.w/2,r.y);ctx.lineTo(r.x+r.w/2,r.y+r.h);ctx.stroke();ctx.setLineDash([])} }
 // Sidewalks and distinctive buildings
 for(const b of buildings){ctx.fillStyle='rgba(47,64,48,.15)';ctx.fillRect(b.x-5,b.y+b.h-3,b.w+10,13);ctx.fillStyle='#f0e9d8';ctx.fillRect(b.x-7,b.y-7,b.w+14,b.h+14);ctx.fillStyle=b.color;ctx.fillRect(b.x,b.y,b.w,b.h);ctx.fillStyle='rgba(255,255,255,.2)';ctx.fillRect(b.x+7,b.y+7,b.w-14,12);
  // Roof rhythm: window pairs and a door create readable tiny shop fronts
  const cols=Math.max(2,Math.floor(b.w/65));for(let i=0;i<cols;i++){let wx=b.x+20+i*(b.w-45)/Math.max(1,cols-1);ctx.fillStyle='#d9eee2';ctx.fillRect(wx,b.y+35,17,20);ctx.strokeStyle='rgba(48,77,64,.28)';ctx.strokeRect(wx,b.y+35,17,20);ctx.fillStyle='#476153';ctx.fillRect(wx+7,b.y+35,2,20)}
  ctx.fillStyle='#614b3c';ctx.fillRect(b.x+b.w/2-9,b.y+b.h-42,18,42);ctx.fillStyle='#e8dfc5';ctx.fillRect(b.x+b.w/2-35,b.y+b.h-57,70,16);ctx.fillStyle='#3b4d40';ctx.font='bold 9px system-ui';ctx.textAlign='center';ctx.fillText(b.name,b.x+b.w/2,b.y+b.h-46);
  ctx.fillStyle='rgba(255,252,238,.5)';ctx.fillRect(b.x+14,b.y+b.h-9,b.w-28,3);
 }
 // Decorative awnings, lamps and leafy trees
 for(const b of buildings.filter(q=>q.detail==='shop')){ctx.fillStyle='#fff0d6';ctx.fillRect(b.x+b.w/2-30,b.y+b.h-59,60,8);for(let i=0;i<5;i++){ctx.fillStyle=i%2?'#ef8b67':'#f3d9b2';ctx.beginPath();ctx.moveTo(b.x+b.w/2-30+i*12,b.y+b.h-51);ctx.lineTo(b.x+b.w/2-18+i*12,b.y+b.h-51);ctx.lineTo(b.x+b.w/2-18+i*12,b.y+b.h-45);ctx.lineTo(b.x+b.w/2-24+i*12,b.y+b.h-42);ctx.lineTo(b.x+b.w/2-30+i*12,b.y+b.h-45);ctx.fill()}}
 for(const t of trees){ctx.fillStyle='rgba(48,64,48,.19)';ctx.beginPath();ctx.ellipse(t.x+4,t.y+8,t.r*1.12,t.r*.72,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#795b42';ctx.fillRect(t.x-2,t.y-1,4,12);ctx.fillStyle='#4b8c62';ctx.beginPath();ctx.arc(t.x,t.y-4,t.r,0,Math.PI*2);ctx.fill();ctx.fillStyle='#65a975';ctx.beginPath();ctx.arc(t.x-4,t.y-8,t.r*.62,0,Math.PI*2);ctx.fill()}
 for(const p of props){ctx.fillStyle='#455a4d';ctx.fillRect(p.x-3,p.y-17,6,25);ctx.fillStyle='#f4e3a8';ctx.beginPath();ctx.arc(p.x,p.y-18,6,0,Math.PI*2);ctx.fill()}
 // Extra pier boardwalk and bollards
 for(let i=0;i<18;i++){let x=160+i*138;ctx.fillStyle='#d0b183';ctx.fillRect(x,1633,75,10);ctx.fillStyle='#efdfb9';ctx.fillRect(x,1632,75,2);ctx.fillStyle='#557d70';ctx.beginPath();ctx.arc(x+35,1660,11,0,Math.PI*2);ctx.fill();ctx.fillStyle='#e9ead3';ctx.beginPath();ctx.arc(x+31,1656,3,0,Math.PI*2);ctx.fill()}
 ctx.textAlign='left';
}
function drawMarker(x,y,color,label,pulse=true){let phase=worldTime*2.7,rad=pulse?17+Math.sin(phase)*3:15;ctx.globalAlpha=.16;ctx.fillStyle=color;ctx.beginPath();ctx.arc(x,y,rad+10,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;ctx.fillStyle=color;ctx.beginPath();ctx.arc(x,y,rad,0,Math.PI*2);ctx.fill();ctx.fillStyle='white';ctx.font='900 14px system-ui';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(label,x,y+.5);ctx.textBaseline='alphabetic';ctx.textAlign='left'}
function drawPerson(x,y,color,name,isPlayer=false){ctx.fillStyle='rgba(28,45,36,.2)';ctx.beginPath();ctx.ellipse(x,y+12,12,5,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#f4d0aa';ctx.beginPath();ctx.arc(x,y-5,8,0,Math.PI*2);ctx.fill();ctx.fillStyle=color;ctx.beginPath();ctx.roundRect(x-9,y+1,18,17,6);ctx.fill();ctx.fillStyle='#263a31';ctx.fillRect(x-7,y+15,5,7);ctx.fillRect(x+3,y+15,5,7);if(isPlayer){ctx.fillStyle='#f0b660';ctx.fillRect(x-8,y-14,16,5);ctx.fillRect(x-5,y-20,11,7);ctx.fillStyle='#fff';ctx.fillRect(x+player.face*2,y-7,2,2)}else{ctx.fillStyle='#4c473a';ctx.fillRect(x-8,y-13,16,3);ctx.fillStyle='rgba(255,255,255,.9)';ctx.font='bold 9px system-ui';ctx.textAlign='center';ctx.fillText(name,x,y-24);ctx.textAlign='left'}}
function activeTarget(){if(!activeJob)return null;return activeJob.kind==='deliver'&&jobStage===0?activeJob.from:activeJob.to}
function render(){ctx.clearRect(0,0,vw,vh);ctx.save();ctx.translate(-camera.x,-camera.y);drawWorld();
 for(const s of scrap)if(!s.taken){ctx.fillStyle='#f3cb66';ctx.beginPath();ctx.arc(s.x,s.y,8+Math.sin(worldTime*3+s.x)*1.5,0,Math.PI*2);ctx.fill();ctx.fillStyle='#fff2be';ctx.fillRect(s.x-2,s.y-4,4,8)}
 for(let i=0;i<jobs.length;i++){const j=jobs[i];if(completed.has(j.id))continue;if(activeJob&&activeJob.id===j.id){const target=activeTarget();drawMarker(target.x,target.y,'#ff8153','!');}else if(!activeJob){drawMarker(j.from.x,j.from.y,'#f28a55','✦',false)}}
 for(const n of npcs)drawPerson(n.x,n.y,n.color,n.name,false);
 if(activeJob&&activeJob.id==='lost'&&jobStage===1)drawPerson(activeJob.to.x,activeJob.to.y,'#bd8a55','Pip',false);
 drawPerson(player.x,player.y,'#357b66','Mika',true);
 ctx.restore();drawMini();
}
function drawMini(){const w=mini.clientWidth,h=mini.clientHeight;mx.clearRect(0,0,w,h);mx.fillStyle='#bfd6ac';mx.fillRect(0,0,w,h);mx.fillStyle='#8cc6bd';mx.fillRect(0,h*.84,w,h*.16);mx.fillStyle='#a0a193';for(const r of roads)mx.fillRect(r.x/W*w,r.y/H*h,r.w/W*w,r.h/H*h);for(const b of buildings){mx.fillStyle=b.color;mx.fillRect(b.x/W*w,b.y/H*h,b.w/W*w,b.h/H*h)}if(activeTarget()){mx.fillStyle='#ff8055';mx.beginPath();mx.arc(activeTarget().x/W*w,activeTarget().y/H*h,3.7,0,Math.PI*2);mx.fill()}mx.fillStyle='#fff';mx.beginPath();mx.arc(player.x/W*w,player.y/H*h,4,0,Math.PI*2);mx.fill();mx.strokeStyle='#285746';mx.lineWidth=1.5;mx.stroke()}

function nearby(){let best=null,dist=Infinity;const candidates=[];if(activeJob){let t=activeTarget();candidates.push({x:t.x,y:t.y,type:'job',label:activeJob.kind==='deliver'&&jobStage===0?'Pick up the item':'Complete the job'});}
 for(const n of npcs)candidates.push({x:n.x,y:n.y,type:'npc',obj:n,label:`Talk to ${n.name}`});for(const s of scrap)if(!s.taken)candidates.push({x:s.x,y:s.y,type:'scrap',obj:s,label:`Collect salvage · +¢ ${s.value}`});for(const j of jobs)if(!completed.has(j.id)&&(!activeJob||activeJob.id===j.id)&&!(activeJob&&activeJob.id===j.id))candidates.push({x:j.from.x,y:j.from.y,type:'offer',obj:j,label:`Start “${j.title}” · +¢ ${j.pay}`});
 for(const c of candidates){let d=Math.hypot(c.x-player.x,c.y-player.y);if(d<dist&&d<58){best=c;dist=d}}return best}
function showToast(t){let el=document.getElementById('toast');el.textContent=t;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}
function updateUI(){document.getElementById('money').textContent='¢ '+player.coins;let mins=Math.floor(worldTime*2),hh=8+Math.floor(mins/60),mm=mins%60;document.getElementById('day').textContent=`01 · ${String(hh%24).padStart(2,'0')}:${String(mm).padStart(2,'0')}`;
 const title=document.getElementById('missionTitle'),tag=document.getElementById('missionTag'),text=document.getElementById('missionText'),obj=document.getElementById('objective'),reward=document.getElementById('reward'),prog=document.getElementById('progress');if(activeJob){tag.textContent=activeJob.tag;title.textContent=activeJob.title;text.textContent=activeJob.desc;obj.textContent=activeJob.steps[Math.min(jobStage,1)];reward.textContent=`+¢ ${activeJob.pay}`;prog.style.width=jobStage?'55%':'15%'}else if(completed.size===jobs.length){tag.textContent='DAY WELL SPENT';title.textContent='Sunbreak is brighter';text.textContent='You helped the whole neighborhood. Take a breather, explore the boardwalk, and collect a little salvage.';obj.textContent='All local jobs done';reward.textContent='✦';prog.style.width='100%'}else{tag.textContent='LOCAL NOTICEBOARD';title.textContent='Good morning, Mika';text.textContent='The neighborhood could use a hand. Find an orange star and lend a hand.';obj.textContent=`${completed.size} / ${jobs.length} jobs complete`;reward.textContent=`+¢ ${jobs.filter(j=>!completed.has(j.id)).reduce((a,j)=>a+j.pay,0)}`;prog.style.width=`${completed.size/jobs.length*100}%`}
 const n=nearby(),hint=document.getElementById('hint');if(n){hint.classList.add('show');document.getElementById('hintText').textContent=n.label}else hint.classList.remove('show')}
function interact(){const c=nearby();if(!c){showToast('Nothing close by. Look for an orange star on the map.');return}if(c.type==='scrap'){c.obj.taken=true;player.coins+=c.obj.value;showToast(`Found useful salvage · +¢ ${c.obj.value}`)}else if(c.type==='npc'){let n=c.obj;showToast(n.talk);let offer=jobs.find(j=>j.from.name===n.name||j.from.name===n.name.replace('’s',''));if(offer&&!activeJob&&!completed.has(offer.id))startJob(offer)}else if(c.type==='offer')startJob(c.obj);else if(c.type==='job'){if(activeJob.kind==='deliver'&&jobStage===0){jobStage=1;showToast('Careful, you’ve got it! Bring it to the marked spot.')}else finishJob()};updateUI()}
function startJob(j){if(activeJob)return;activeJob=j;jobStage=0;showToast(`New favor: ${j.title}`);updateUI()}
function finishJob(){let j=activeJob;completed.add(j.id);player.coins+=j.pay;activeJob=null;jobStage=0;showToast(`${j.title} complete · +¢ ${j.pay}`);updateUI()}
function update(dt){worldTime+=dt;let ix=(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0)+touch.x,iy=(keys.KeyS||keys.ArrowDown?1:0)-(keys.KeyW||keys.ArrowUp?1:0)+touch.y;let len=Math.hypot(ix,iy);if(len>0){ix/=len;iy/=len;player.walk+=dt*10;player.face=ix<-.1?-1:ix>.1?1:player.face}let running=keys.ShiftLeft||keys.ShiftRight||touch.run;let sp=player.speed*(running&&player.stamina>0?1.52:1);player.stamina=running&&len>0?Math.max(0,player.stamina-dt*28):Math.min(100,player.stamina+dt*17);let nx=player.x+ix*sp*dt,ny=player.y+iy*sp*dt;if(!isBlocked(nx,player.y))player.x=nx;if(!isBlocked(player.x,ny))player.y=ny;
 camera.x=Math.max(0,Math.min(W-vw,player.x-vw*.5));camera.y=Math.max(0,Math.min(H-vh,player.y-vh*.5));updateUI();render()}
function loop(t){let dt=Math.min(.04,(t-last)/1000||0);last=t;if(playing)update(dt);else render();requestAnimationFrame(loop)}requestAnimationFrame(loop);
addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space'].includes(e.code))e.preventDefault();keys[e.code]=true;if(e.code==='KeyE'&&!e.repeat&&playing)interact();if(e.code==='KeyM'&&!e.repeat)document.getElementById('minimap').style.display=document.getElementById('minimap').style.display==='none'?'block':'none'});addEventListener('keyup',e=>keys[e.code]=false);addEventListener('blur',()=>{for(const k in keys)keys[k]=false});
document.getElementById('start').onclick=()=>{playing=true;document.getElementById('intro').classList.add('hide');showToast('Welcome to Sunbreak, Mika!')};document.querySelectorAll('[data-dir]').forEach(b=>{const dir=b.dataset.dir,vec={up:[0,-1],down:[0,1],left:[-1,0],right:[1,0]};let set=v=>{touch.x=v?vec[dir][0]:0;touch.y=v?vec[dir][1]:0};b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);set(true)});b.addEventListener('pointerup',()=>set(false));b.addEventListener('pointercancel',()=>set(false))});document.querySelector('[data-run]').addEventListener('pointerdown',e=>{e.preventDefault();touch.run=true});['pointerup','pointercancel','pointerleave'].forEach(ev=>document.querySelector('[data-run]').addEventListener(ev,()=>touch.run=false));document.querySelector('[data-action]').addEventListener('pointerdown',e=>{e.preventDefault();if(playing)interact()});
updateUI();
})();
</script></body></html>

