for(let y=0;y<1700;y+=400)for(let x=0;x<2400;x+=500){ctx.fillStyle='#d9e7ce';ctx.fillRect(x+8,y+9,480,375)}
for(const r of roads){ctx.fillStyle='#e7ddc6';ctx.fillRect(r.x-5,r.y-5,r.w+10,r.h+10);ctx.fillStyle='#9da092';ctx.fillRect(r.x,r.y,r.w,r.h);ctx.strokeStyle='#e8d698';ctx.lineWidth=2;ctx.setLineDash([17,18]);ctx.beginPath();if(r.w>r.h){ctx.moveTo(r.x,r.y+r.h/2);ctx.lineTo(r.x+r.w,r.y+r.h/2)}else{ctx.moveTo(r.x+r.w/2,r.y);ctx.lineTo(r.x+r.w/2,r.y+r.h)}ctx.stroke();ctx.setLineDash([])}
for(const q of buildings){ctx.fillStyle='#34443625';ctx.fillRect(q.x-4,q.y+q.h-1,q.w+8,12);ctx.fillStyle='#f0e9d8';ctx.fillRect(q.x-6,q.y-6,q.w+12,q.h+12);ctx.fillStyle=q.color;ctx.fillRect(q.x,q.y,q.w,q.h);ctx.fillStyle='#ffffff33';ctx.fillRect(q.x+7,q.y+7,q.w-14,12);let cols=Math.max(2,Math.floor(q.w/65));for(let i=0;i<cols;i++){let xx=q.x+20+i*(q.w-45)/Math.max(1,cols-1);ctx.fillStyle='#d9eee2';ctx.fillRect(xx,q.y+36,17,20)}ctx.fillStyle='#59493d';ctx.fillRect(q.x+q.w/2-9,q.y+q.h-43,18,43);ctx.fillStyle='#f8efd9';ctx.fillRect(q.x+q.w/2-42,q.y+q.h-61,84,17);ctx.fillStyle='#30473a';ctx.font='bold 10px system-ui';ctx.textAlign='center';ctx.fillText(q.name,q.x+q.w/2,q.y+q.h-49)}
// park trees with layered leaf canopies
for(let i=0;i<65;i++){let x=35+(i*181)%2340,y=28+(i*237)%1430;if(roads.some(r=>x>r.x-16&&x<r.x+r.w+16&&y>r.y-16&&y<r.y+r.h+16)||buildings.some(b=>x>b.x-12&&x<b.x+b.w+12&&y>b.y-12&&y<b.y+b.h+12))continue;ctx.fillStyle='#755c43';ctx.fillRect(x-2,y,4,10);ctx.fillStyle='#4b8c62';ctx.beginPath();ctx.arc(x,y-3,11+(i%3)*2,0,7);ctx.fill();ctx.fillStyle='#67a977';ctx.beginPath();ctx.arc(x-4,y-8,7,0,7);ctx.fill()}
ctx.textAlign='left'}
function person(x,y,color,label,hero=false){ctx.fillStyle='#263a3150';ctx.beginPath();ctx.ellipse(x,y+12,12,5,0,0,7);ctx.fill();ctx.fillStyle='#f2ccaa';ctx.beginPath();ctx.arc(x,y-5,8,0,7);ctx.fill();ctx.fillStyle=color;ctx.beginPath();ctx.roundRect(x-9,y+1,18,18,6);ctx.fill();ctx.fillStyle='#29372e';ctx.fillRect(x-7,y+16,5,6);ctx.fillRect(x+3,y+16,5,6);if(hero){ctx.fillStyle='#f2b45e';ctx.fillRect(x-9,y-14,18,5);ctx.fillRect(x-5,y-20,12,7);ctx.fillStyle='white';ctx.fillRect(x+player.face*2,y-7,2,2)}else{ctx.fillStyle='#51473a';ctx.fillRect(x-8,y-13,16,3);ctx.fillStyle='#28352e';ctx.font='bold 10px system-ui';ctx.textAlign='center';ctx.fillText(label,x,y-24);ctx.textAlign='left'}}
function marker(x,y){let r=15+Math.sin(time*5)*3;ctx.fillStyle='#f28a5533';ctx.beginPath();ctx.arc(x,y,r+9,0,7);ctx.fill();ctx.fillStyle='#f18150';ctx.beginPath();ctx.arc(x,y,r,0,7);ctx.fill();ctx.fillStyle='white';ctx.font='bold 15px system-ui';ctx.textAlign='center';ctx.fillText('✦',x,y+5);ctx.textAlign='left'}
