function nearby(){let all=[];if(active){let t=target();all.push({x:t.x,y:t.y,type:'target',label:stage===0?'Pick up the item':'Finish the job'})}else for(const j of jobs.slice(done))all.push({x:j.from.x,y:j.from.y,type:'offer',job:j,label:`Start “${j.name}” · +¢ ${j.pay}`});for(const s of scraps)if(!s.taken)all.push({x:s.x,y:s.y,type:'scrap',scrap:s,label:`Collect salvage · +¢ ${s.value}`});let result=null,dist=62;for(const c of all){let d=Math.hypot(c.x-player.x,c.y-player.y);if(d<dist){dist=d;result=c}}return result}
