function nearest(){const list=[];if(active){const t=target();list.push({x:t.x,y:t.y,type:'target',label:stage===0?'Pick up the item':'Complete the favor'})}else for(const j of jobs)if(!done.has(j.name))list.push({x:j.from.x,y:j.from.y,type:'offer',job:j,label:`Start “${j.name}” · +¢ ${j.pay}`});for(const s of scraps)if(!s.taken)list.push({x:s.x,y:s.y,type:'scrap',scrap:s,label:`Collect salvage · +¢ ${s.value}`});let best=null,distance=64;for(const c of list){const d=Math.hypot(c.x-player.x,c.y-player.y);if(d<distance){distance=d;best=c}}return best}
const $=s=>document.querySelector(s),hint=$('#hint'),toastBox=$('#toast'),missionTitle=$('#title'),missionTag=$('#tag'),missionDesc=$('#desc'),objective=$('#objective'),moneyBox=$('#money');let toastTimer;
function toast(message){toastBox.textContent=message;toastBox.classList.add('on');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toastBox.classList.remove('on'),2200)}
function refreshHud(){moneyBox.textContent=`¢ ${money}`;if(active){missionTag.textContent=`NEIGHBORHOOD JOB · ${stage===0?'PICKUP':'IN PROGRESS'}`;missionTitle.textContent=active.name;missionDesc.textContent=active.desc;objective.textContent=stage===0?`Collect the item from ${active.from.label}.`:`Deliver to ${active.to.label} · +¢ ${active.pay}`}else{missionTag.textContent='LOCAL NOTICEBOARD';missionTitle.textContent=done.size===3?'Sunbreak says thanks!':'Good morning, Mika';missionDesc.textContent=done.size===3?'Every neighbor has been helped. Keep exploring and gathering salvage.':'The neighborhood could use a hand. Find an orange star and lend a hand.';objective.textContent=`Explore Sunbreak · ${done.size} / 3 jobs`}}
function interact(){if(!playing)return;const choice=nearest();if(!choice){toast('Nothing nearby — follow an orange star or find salvage.');return}if(choice.type==='scrap'){choice.scrap.taken=true;money+=choice.scrap.value;toast(`Salvage found! +¢ ${choice.scrap.value}`);refreshHud();return}if(choice.type==='offer'){active=choice.job;stage=1;toast(`“${active.name}” accepted! Head to ${active.to.label}.`);refreshHud();return}if(stage===0){stage=1;toast('Item collected — deliver it to your neighbor!');refreshHud();return}money+=active.pay;done.add(active.name);toast(`${active.name} complete! +¢ ${active.pay}`);active=null;stage=0;refreshHud()}
function update(dt){let dx=(keys.ArrowRight||keys.d||touch.x>0?1:0)-(keys.ArrowLeft||keys.a||touch.x<0?1:0),dy=(keys.ArrowDown||keys.s||touch.y>0?1:0)-(keys.ArrowUp||keys.w||touch.y<0?1:0);if(dx||dy){const mag=Math.hypot(dx,dy);dx/=mag;dy/=mag;const speed=(keys.Shift?235:165)*dt,nx=player.x+dx*speed,ny=player.y+dy*speed;if(!blocked(nx,player.y))player.x=nx;if(!blocked(player.x,ny))player.y=ny;if(dx)player.face=Math.sign(dx)}const cw=Math.min(w,world.w),ch=Math.min(h,world.h),cx=Math.max(0,Math.min(world.w-cw,player.x-w/2)),cy=Math.max(0,Math.min(world.h-ch,player.y-h/2));camera.x=cx;camera.y=cy;const choice=nearest();if(playing&&choice){hint.style.display='block';hint.textContent=`E  ·  ${choice.label}`}else hint.style.display='none'}
function frame(now){const dt=Math.min(.04,(now-last)/1000||0);last=now;time+=dt;if(playing)update(dt);else{camera.x=Math.max(0,Math.min(world.w-w,player.x-w/2));camera.y=Math.max(0,Math.min(world.h-h,player.y-h/2))}render();requestAnimationFrame(frame)}
function setDirection(button,down){const d=button.dataset.dir;if(d==='left')touch.x=down?-1:(touch.x<0?0:touch.x);if(d==='right')touch.x=down?1:(touch.x>0?0:touch.x);if(d==='up')touch.y=down?-1:(touch.y<0?0:touch.y);if(d==='down')touch.y=down?1:(touch.y>0?0:touch.y)}
document.querySelectorAll('.tb').forEach(button=>{button.addEventListener('pointerdown',e=>{e.preventDefault();button.setPointerCapture(e.pointerId);setDirection(button,true)});for(const ev of ['pointerup','pointercancel','lostpointercapture'])button.addEventListener(ev,()=>setDirection(button,false))});$('[data-do]').addEventListener('pointerdown',e=>{e.preventDefault();interact()});$('#start').addEventListener('click',()=>{$('#intro').classList.add('hide');playing=true;toast('A lovely day to lend a hand. Find an orange star!')});
window.addEventListener('keydown',e=>{const key=e.key.length===1?e.key.toLowerCase():e.key;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();keys[key]=true;if(key==='e'&&!e.repeat)interact();if(key==='m'&&!e.repeat){const box=$('#mapbox');box.style.display=box.style.display==='none'?'block':'none'}});window.addEventListener('keyup',e=>{const key=e.key.length===1?e.key.toLowerCase():e.key;keys[key]=false});window.addEventListener('blur',()=>{for(const key in keys)keys[key]=false;touch.x=touch.y=0});window.addEventListener('resize',resize);buildMap();resize();refreshHud();requestAnimationFrame(frame);
})();
